const http = require("http");

const PRIX = { riz: 600, huile: 1500, sel: 150 };

function envoyerJSON(res, statut, donnees) {
  res.writeHead(statut, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(donnees));
}

const serveur = http.createServer((req, res) => {
  const article = new URL(req.url, "http://localhost").searchParams.get("article");
  if (PRIX[article] === undefined) return envoyerJSON(res, 404, { erreur: "article inconnu" });
  envoyerJSON(res, 200, { article, prix: PRIX[article] });
});

